#{projectId}
AND member_role IN ('SERVICE_MANAGER_L1', 'SERVICE_MANAGER_L2') AND status = 'ACTIVE' AND deleted = b'0' AND (effective_from IS NULL OR effective_from <= #{query.effectiveAt}) AND (effective_to IS NULL OR effective_to > #{query.effectiveAt}) ORDER BY project_id, member_role, site_id, department_id, CASE WHEN assignment_type = 'PRIMARY' OR assignment_type IS NULL THEN 0 ELSE 1 END, id

