SELECT id, project_id, user_id, member_role, assignment_type, version, tenant_id FROM proj_project_member_assignment WHERE tenant_id = #{query.tenantId} AND project_id = #{query.projectId} AND user_id = #{query.userId}
AND member_role IN
#{roleCode}
AND 1 = 0
